mapper.select:
select hlii.*, ( select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = hlii.insure_company ) as insure_company_n, (select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code = 'HLS.BASIS_OF_ASSERTING' and scvb.value = hlii.BASIS_OF_ASSERTING ) BASIS_OF_ASSERTING_N, (select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code = 'HLS.IF_PROVIDE_ORIGINAL' and scvb.value = hlii.IF_PROVIDE_ORIGINAL ) IF_PROVIDE_ORIGINAL_N, (select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code = 'INSURE_CATEGORY' and scvb.value = hlii.INSURE_CATEGORY ) INSURE_CATEGORY_N, (select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code = 'SYS.YES_NO' and scvb.value = hlii.IF_INSURE_COVER_ITEM ) IF_INSURE_COVER_ITEM_N, (select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code = 'SYS.YES_NO' and scvb.value = hlii.IF_APPROVAL_NOTICE ) IF_APPROVAL_NOTICE_N, (select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code = 'SYS.YES_NO' and scvb.value = hlii.CONTRACT_AGREEMENT ) CONTRACT_AGREEMENT_N, (select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code = 'SYS.YES_NO' and scvb.value = hlii.INSURANCE_POLICY_ORIGINAL ) INSURANCE_POLICY_ORIGINAL_N, (select scvb.meaning from sys_code_value_b scvb , sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code = 'SYS.YES_NO' and scvb.value = hlii.SINGLE_ORIGINAL ) SINGLE_ORIGINAL_N from hls_lease_item_insure hlii
1=1
and hlii.insure_id = #{insureId}
